output.text:
{"connection_id": "BC-5166a7fc0f2c80816bb3", "ref": "Augustine, Tractates on John 69 (on John 14:4-6)", "target": "sec1", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Christ as the way to the Father", "note": "Augustine reads Jesus’s “I am the way” as Christ himself mediating access to the Father; this interprets the route-and-destination relation as a person rather than a road."}
{"connection_id": "BC-111e64339176518e39b8", "ref": "Didache 1.1", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "two ways of life and death", "note": "The teaching opens by distinguishing a way of life from a way of death; it places the commentary’s contrast between the guided path and its opposite in early Christian moral instruction."}
{"connection_id": "BC-f54a75733bd2881b6fd2", "ref": "Didache 1:1", "target": "sec1", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "the way of life and the way of death", "note": "The Didache's opening two-ways instruction turns path language into a catechetical division between life and death, a compact Christian interpretive frame for the single way and its opposed courses."}
{"connection_id": "BC-6b44c6bdd56627acc8ae", "ref": "Epistle of Barnabas 18.1", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "two ways of light and darkness", "note": "Barnabas describes two ways, light and darkness, under different authorities; this makes the competing routes a community’s ethical and spiritual allegiance."}
{"connection_id": "BC-547e33ae3fe382514cdd", "ref": "SBLGNT:1John.2.11", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "walker in darkness does not know where going", "note": "The person who walks in darkness cannot know the destination because darkness blinds the eyes, a direct cognitive and spatial rendering of being lost."}
{"connection_id": "BC-6e8186b2968257fc9d42", "ref": "SBLGNT:1John.2.6", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "walk as the exemplar walked", "note": "The one who remains in Christ is obliged to walk as he walked, making a prior walk an exemplary track for later followers."}
{"connection_id": "BC-360c8352ec785a3b3f80", "ref": "SBLGNT:1Pet.2.25", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "straying sheep return to their shepherd", "note": "The readers were straying like sheep and have now returned to the shepherd and guardian; the route from loss to restored guidance is explicit."}
{"connection_id": "BC-f0f343ef08bd31345e89", "ref": "SBLGNT:1Pet.2.25", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "straying sheep returned to shepherd and overseer", "note": "The audience was straying like sheep but has returned to the shepherd and overseer of souls, combining lostness, return, and a restoring guide."}
{"connection_id": "BC-887e1af928f5f825102d", "ref": "SBLGNT:1Thess.2.12", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "walk worthy toward God's kingdom and glory", "note": "Paul urges conduct worthy of the God who calls believers into kingdom and glory, joining a moral walk to a destination beyond the journey."}
{"connection_id": "BC-bf582896d454064cec54", "ref": "SBLGNT:1Thess.3.11", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "God directs a journey's way", "note": "Paul asks God and the Lord Jesus to direct his way to the recipients, a specific travel prayer that supplies a less developed but concrete guide-to-destination parallel."}
{"connection_id": "BC-a3ae4bd2bc92436711cf", "ref": "SBLGNT:2Cor.11.3", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the serpent leads minds away from devotion", "note": "Paul fears that, as the serpent deceived Eve, the community’s minds may be led astray from devotion to Christ; this gives the commentary’s ambushing adversary a specific Christian counterpart."}
{"connection_id": "BC-3a60bbf67a4e8e1efd0a", "ref": "SBLGNT:2Cor.5.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "judgment accounts for deeds done in life", "note": "All appear before the judgment seat to receive for what they did in the body, connecting the commentary’s Day of Reckoning with a person’s lived course."}
{"connection_id": "BC-7c8eb9f58fa96c63dc8f", "ref": "SBLGNT:2John.1.6", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "love is walking according to commandments", "note": "The epistle defines love as walking according to God's commandments, directly coupling the commentary's worshipful path with repeated ethical practice."}
{"connection_id": "BC-bd43c2289e6806f3bda7", "ref": "SBLGNT:2Pet.2.15", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "forsaking the straight way for error", "note": "The false teachers leave the straight way and go astray after Balaam; it directly depicts abandoning the route and its ethical course."}
{"connection_id": "BC-e8b610f5f66207bac07c", "ref": "SBLGNT:2Pet.2.15", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "forsaking the straight way and going astray", "note": "The false teachers explicitly abandon the straight way and wander into Balaam's course, one of the closest New Testament inversions of the commentary's daḷḷīn."}
{"connection_id": "BC-d144e0e57d5ebb32c904", "ref": "SBLGNT:Acts.13.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Elymas perverts the straight ways of the Lord", "note": "Paul accuses Elymas of trying to make the Lord’s straight ways crooked; this is a direct Christian image of an adversary obstructing the right route."}
{"connection_id": "BC-374ae1a2adb46fb71ac3", "ref": "SBLGNT:Acts.13.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "crooking the Lord's straight ways", "note": "The opponent is accused of making the Lord's straight ways crooked, an exact verbal and moral inverse to keeping a course mustaqīm."}
{"connection_id": "BC-296b33a0dc030fb11923", "ref": "SBLGNT:Acts.16.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the group infers its destination from the call", "note": "The travelers conclude that God has called them to preach in Macedonia and set out; guidance becomes a shared decision about where to go."}
{"connection_id": "BC-795327322c42bb280691", "ref": "SBLGNT:Acts.16.9", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "a vision calls the travelers toward Macedonia", "note": "Paul sees a Macedonian asking him to come and help; the call gives a specific divine direction for a traveling group."}
{"connection_id": "BC-93fa2f161eb6314f9cda", "ref": "SBLGNT:Acts.18.25", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Apollos is instructed in the Lord’s way but incompletely", "note": "Apollos knows and teaches the way of the Lord but knows only John’s baptism; his case makes clear that a guide can have real direction while still lacking part of the route."}
{"connection_id": "BC-6571ddb71bb64fb1e858", "ref": "SBLGNT:Acts.18.25", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "instructed in the way of the Lord", "note": "Apollos is instructed in the way of the Lord and teaches concerning Jesus, giving the Way an explicit pedagogical form alongside the commentary's guide who makes a path known."}
{"connection_id": "BC-c08abd470a130e7d73cb", "ref": "SBLGNT:Acts.18.26", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Priscilla and Aquila explain the way more accurately", "note": "The couple takes Apollos aside and explains the way of God more accurately; a community helps its guide correct and complete his direction."}
{"connection_id": "BC-71443938de7fbd5e5974", "ref": "SBLGNT:Acts.24.14", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "worship according to the Way", "note": "Paul says he worships God according to the Way; this uniquely joins the commentary’s worship and path images in one statement."}
{"connection_id": "BC-4177d37cbaafe9e749cf", "ref": "SBLGNT:Acts.24.14", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "worship according to the Way", "note": "Paul says that he worships the ancestral God according to the Way, showing a Christian community in which worship and a named collective road are one identity."}
{"connection_id": "BC-d975f679cac4680b7849", "ref": "SBLGNT:Acts.8.26", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "angel directs Philip onto the Gaza road", "note": "An angel sends Philip onto a specific desert road, making divine guidance an actual route instruction before the encounter with the traveler."}
{"connection_id": "BC-7b7e8e2facf97b072dbc", "ref": "SBLGNT:Acts.8.31", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "a traveler asks for someone to guide him", "note": "On the road, the Ethiopian says he cannot understand without a guide, and Philip joins him to interpret the text; this makes guidance both travel and instruction."}
{"connection_id": "BC-d8b1a60e85ec53e97658", "ref": "SBLGNT:Acts.8.31", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "unless someone guides me", "note": "On the road, the Ethiopian says he cannot understand unless someone guides him, a direct verbal and scene-level counterpart to needing a guide for the way."}
{"connection_id": "BC-acce8d62d8cdbebc4bb9", "ref": "SBLGNT:Acts.9.2", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the followers are called people of the Way", "note": "Saul seeks those who belong to the Way; the path is the name of a community, not merely an individual direction."}
{"connection_id": "BC-c88dadd002c9e13f5c72", "ref": "SBLGNT:Eph.2.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "people walk in works prepared by God", "note": "The community is created for good works God prepared beforehand for them to walk in; the path is a sustained practice laid out by God."}
{"connection_id": "BC-18811a3607a5e764c889", "ref": "SBLGNT:Eph.2.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "good works prepared beforehand to walk in", "note": "God prepares good works beforehand so that believers may walk in them, making a divinely prepared course the form of sustained practice."}
{"connection_id": "BC-326319ec3a1953a9f442", "ref": "SBLGNT:Gal.2.14", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "not walking straight toward gospel truth", "note": "Paul says certain conduct is not walking straight toward the gospel's truth, making upright walking a communal ethical test rather than a mere route description."}
{"connection_id": "BC-b6ca443c9d02aa206dc1", "ref": "SBLGNT:Heb.10.20", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "new and living way through the veil", "note": "The passage calls access through the sanctuary veil a new and living way, making the route itself the means of reaching God's dwelling presence."}
{"connection_id": "BC-c0a696713daeeff71ad2", "ref": "SBLGNT:Heb.11.16", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the travelers seek a homeland and a prepared city", "note": "The faithful desire a better country and a city God has prepared; this develops the commentary’s claim that a route is oriented toward a home."}
{"connection_id": "BC-8688cb573735127d559f", "ref": "SBLGNT:Heb.11.16", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "heavenly homeland and a prepared city", "note": "The pilgrims seek a better, heavenly homeland and God prepares a city for them, a destination image that complements the commentary's road-and-house pairing."}
{"connection_id": "BC-697c26d31e417f0a37ef", "ref": "SBLGNT:Heb.11.8", "target": "sec1", "tradition": "incil", "kind": "karsi_anlati", "basis": "Abraham obeys without knowing the destination", "note": "Hebrews says Abraham set out without knowing where he was going; this counterpoint qualifies the commentary’s image of guidance that includes knowing the road’s destination, since faithful following can precede that knowledge."}
{"connection_id": "BC-36a23c6b470182bd422c", "ref": "SBLGNT:Heb.12.1", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "run the course set before the community", "note": "The hearers are told to run with endurance the race set before them; the path becomes a shared course that must be followed to its finish."}
{"connection_id": "BC-835d3e6570da28400f2c", "ref": "SBLGNT:Heb.12.13", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "make straight paths so the lame can be healed", "note": "The hearers must make straight paths for their feet so the lame will not be put out of joint but healed; straightening the route protects struggling travelers."}
{"connection_id": "BC-23bc76f975945e54a98e", "ref": "SBLGNT:Heb.12.13", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "make straight paths for feet", "note": "The congregation must make straight paths for its feet so that the lame are healed rather than put out of joint, adding care for vulnerable walkers to the road image."}
{"connection_id": "BC-0aace705b1ae5eb757d1", "ref": "SBLGNT:Heb.12.2", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Jesus as pioneer and perfecter of the course", "note": "Jesus is named the pioneer and perfecter of faith; this gives the community a forerunner who goes ahead and completes the way."}
{"connection_id": "BC-d479a9aa9eefd1b5d4cc", "ref": "SBLGNT:Heb.13.14", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "no lasting city here, seeking the coming one", "note": "The community has no permanent city here and seeks the coming city, turning road imagery into an ongoing search for a final dwelling."}

{"connection_id": "BC-1652705e996c55e1f81c", "ref": "SBLGNT:Heb.3.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "hearts that continually go astray", "note": "The wilderness generation is described as always going astray in heart and not knowing God’s ways; the passage links lost direction with failure to know the divine route."}
{"connection_id": "BC-967c93bc22ef6913c9b2", "ref": "SBLGNT:Heb.3.10", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "hearts go astray and do not know God's ways", "note": "The citation describes a people always going astray in heart and not knowing God's ways, joining inner deviation to the lost-way language without the commentary's literal traveler scene."}
{"connection_id": "BC-4dc7a9119a70235dc33a", "ref": "SBLGNT:Heb.6.20", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Jesus enters ahead as a forerunner", "note": "Jesus goes into the sanctuary as a forerunner on behalf of others; the text directly connects precedence with leading people toward a destination."}
{"connection_id": "BC-1eaef811f7f90b7e34bc", "ref": "SBLGNT:Heb.9.8", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "way into the sanctuary not yet manifest", "note": "The Spirit indicates that the way into the holy place was not yet open, supplying the inaccessible-side context for the later new and living way."}
{"connection_id": "BC-a9974baea864b0e92bca", "ref": "SBLGNT:Jas.5.19", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "a wanderer is turned back from error", "note": "A person who wanders from the truth is brought back by another; the passage gives the commentary’s companions calling the lost traveler a communal form."}
{"connection_id": "BC-b94ea827248356e3c1de", "ref": "SBLGNT:Jas.5.19", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "wanderer from truth brought back", "note": "The community is charged with bringing back anyone who wanders from truth, closely paralleling the commentary's companions calling the bewildered person back to guidance."}
{"connection_id": "BC-897d4f6f6343088d9368", "ref": "SBLGNT:John.10.4", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "shepherd walks ahead of the sheep", "note": "The shepherd goes before the flock and the sheep follow his voice, matching the commentary’s guide defined by leading from the front."}
{"connection_id": "BC-44ab3a48bd47722cec58", "ref": "SBLGNT:John.10.4", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "shepherd goes ahead and sheep follow", "note": "The shepherd brings out his own sheep, goes before them, and they follow his voice, closely matching the commentary's guide who walks in front and a community that follows."}
{"connection_id": "BC-58b708edfb6efd049315", "ref": "SBLGNT:John.12.26", "target": "sec1", "tradition": "incil", "kind": "karsi_anlati", "basis": "serving Jesus, following him, being where he is", "note": "The commentary's cited Jesus directs worship to God as the straight path; John joins serving Jesus to following him and being where he is, so the object of service and path-following differs materially."}
{"connection_id": "BC-c17c4491b0f7baa506a7", "ref": "SBLGNT:John.12.35", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "walking in darkness means not knowing where one goes", "note": "Jesus warns that the person who walks in darkness does not know where he is going; it directly links lost orientation with darkness."}
{"connection_id": "BC-96167b501439485f6586", "ref": "SBLGNT:John.12.35", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "walker in darkness does not know the destination", "note": "The warning to walk while light is present says darkness overtakes the person who walks without knowing where he goes, a close counterpart to the commentary's disoriented traveler."}
{"connection_id": "BC-65d55f0bb8880e4703c0", "ref": "SBLGNT:John.14.2", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the Father’s house as the destination", "note": "Jesus speaks of many dwelling places in his Father’s house and says he goes to prepare a place; this makes the destination part of knowing the way."}
{"connection_id": "BC-7c9db6486cd59d1abe79", "ref": "SBLGNT:John.14.2", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Father's house and a prepared place", "note": "The many dwelling places and prepared place in the Father's house make explicit the destination side of the commentary's claim that guidance shows a road together with its house."}
{"connection_id": "BC-3549775d3fc90203e1bc", "ref": "SBLGNT:John.14.5", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Thomas does not know the way to the destination", "note": "Thomas says they do not know where Jesus is going and therefore cannot know the way; the exchange dramatizes the commentary’s link between route knowledge and knowing the house."}
{"connection_id": "BC-62afdbb96d32cc8d0800", "ref": "SBLGNT:John.14.6", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Jesus identifies himself as the way to the Father", "note": "The destination is the Father, while Jesus calls himself the way to it; this is a Christian formulation in which the guide and route are one."}
{"connection_id": "BC-5e5445d3c9dec435b405", "ref": "SBLGNT:John.14.6", "target": "sec1", "tradition": "incil", "kind": "karsi_anlati", "basis": "Jesus says he is the way to the Father", "note": "The commentary cites Jesus calling worship of God the straight path; John instead has Jesus identify himself as the way by which one comes to the Father, so the differing identification of the path is the point."}
{"connection_id": "BC-b26925a21e6679c266cf", "ref": "SBLGNT:John.16.13", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Spirit of truth guides into all truth", "note": "The Spirit is promised as a guide into all truth; the guidance is interpretive rather than a road scene, but it preserves the commentary's leading rather than mere information."}
{"connection_id": "BC-86afeb1e562eefb1bbce", "ref": "SBLGNT:John.8.12", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "following the light prevents walking in darkness", "note": "Jesus says the follower will not walk in darkness but have the light of life; this ties following a guide to avoiding the lost traveler’s darkness."}
{"connection_id": "BC-a547e9ea99c95236311f", "ref": "SBLGNT:John.8.12", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "following the light avoids darkness", "note": "Jesus says that the one following him will not walk in darkness but will have the light of life, directly linking leader, walking, light, and non-lost arrival."}
{"connection_id": "BC-acb960a9f27767839c39", "ref": "SBLGNT:Jude.1.13", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "wandering stars reserved for darkness", "note": "Jude calls the false teachers wandering stars destined for darkness; as an inverse to the commentary's stars used for orientation, the link is specific but the text does not portray them as travel guides."}
{"connection_id": "BC-17d5f729227fe5513515", "ref": "SBLGNT:Luke.1.79", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "guiding feet into the way of peace", "note": "The hymn says the dawn will guide feet into the way of peace, directly joining a guide, bodily walking, and a named route."}
{"connection_id": "BC-f27aeb511cb6825f52e1", "ref": "SBLGNT:Luke.1.79", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "light guides feet into the way of peace", "note": "The dawn/light is said to guide feet into the way of peace, turning the commentary's orientation signs into an explicitly footed, divinely directed route."}
{"connection_id": "BC-210da9464b4bd200cb87", "ref": "SBLGNT:Luke.15.4", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "shepherd searches for a sheep that strayed", "note": "The shepherd goes after the one lost sheep until he finds it; this is a direct recovery scene for the commentary’s person who has lost the way."}
{"connection_id": "BC-a0a861d919cf13c25399", "ref": "SBLGNT:Luke.24.15", "target": "sec1", "tradition": "incil", "kind": "karsi_anlati", "basis": "the guide joins travelers from beside them", "note": "On the road to Emmaus, Jesus draws near and walks with the disciples rather than going ahead; this offers a specific counter-image to the commentary’s guide defined by precedence."}
{"connection_id": "BC-66361aa0ac30cfae351d", "ref": "SBLGNT:Luke.24.32", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "scriptural explanation changes how the travelers see the road", "note": "The disciples recall how their hearts burned while Jesus explained the Scriptures on the road; guidance includes interpreting the text during travel."}
{"connection_id": "BC-4d04892b9ee50ff8bb20", "ref": "SBLGNT:Luke.24.33", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "the travelers turn back toward the community", "note": "After recognizing Jesus, the disciples immediately return to Jerusalem; the road that had led away from the group is reversed toward reunion."}
{"connection_id": "BC-34209bddeef10273b696", "ref": "SBLGNT:Luke.3.5", "target": "sec1", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Isaiah's terrain-leveling in a John the Baptist setting", "note": "Luke retains the levelling of valleys, mountains, crookedness, and roughness as preparation for salvation, giving the road construction image a distinct Christian forerunner setting."}
{"connection_id": "BC-0aa3d9b9d26e66cceb11", "ref": "SBLGNT:Luke.9.23", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "following Jesus is taken up daily", "note": "Jesus says a follower must take up the cross daily and follow him; the route is maintained through repeated, embodied commitment."}
{"connection_id": "BC-3e14153158f4b20ae891", "ref": "SBLGNT:Mark.1.2", "target": "sec1", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "messenger sent before to prepare the way", "note": "Mark applies the forerunner formula to John, whose going before prepares the Lord's way; this is a Christian scriptural development of the guide-ahead image."}
{"connection_id": "BC-58c3114a49e115fd1232", "ref": "SBLGNT:Mark.1.3", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "prepare a straight road in the wilderness", "note": "Mark applies the call to prepare the Lord’s way and make paths straight; the route is cleared for the Lord’s arrival, adding a preparatory road to the commentary’s walkable path."}
{"connection_id": "BC-7ce7b3d905934a39888e", "ref": "SBLGNT:Mark.1.3", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "Isaiah’s straight-way call applied to the Lord’s arrival", "note": "Mark uses the wilderness highway text to frame John’s preparation of the Lord’s way; it makes the route a communal expectation of arrival."}
{"connection_id": "BC-1fb235392d61e33a21d7", "ref": "SBLGNT:Mark.1.3", "target": "sec1", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "make the Lord's paths straight", "note": "Mark's wilderness proclamation uses straightened paths as preparation for the Lord's arrival, interpreting prophetic road building as an advent scene."}
{"connection_id": "BC-2722869f8797ad27d956", "ref": "SBLGNT:Mark.10.52", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "blind man gains sight and follows on the way", "note": "The healed blind man immediately follows Jesus on the way, bringing sight, recovery from disorientation, and following a leader into one movement."}
{"connection_id": "BC-436897067b18a2807eaa", "ref": "SBLGNT:Matt.15.14", "target": "sec1", "tradition": "incil", "kind": "motif", "basis": "blind guides lead others into a pit", "note": "Jesus calls the teachers blind guides whose followers fall with them; it adds the danger of a guide who cannot see the right way."}
